const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

(async () => {
  try {
    const rows = await prisma.$queryRawUnsafe(`
      SELECT j.job_name,
             COUNT(*) as cnt,
             MIN(j.selling_price)::text as min_price,
             MAX(j.selling_price)::text as max_price,
             STRING_AGG(DISTINCT COALESCE(b.name,'N/A'), ', ') as brands,
             STRING_AGG(DISTINCT p.project_name, ', ') as sample_projects
      FROM jobs j
      LEFT JOIN brands b ON b.uuid = j.brand_uuid
      LEFT JOIN job_projects jp ON jp.job_uuid = j.job_uuid
      LEFT JOIN projects p ON p.project_uuid = jp.project_uuid
      WHERE j.job_name ~ '^(PL|SL|S)[0-9]+'
      GROUP BY j.job_name
      ORDER BY j.job_name
      LIMIT 200
    `);

    console.log('Pattern jobs:', rows.length);
    for (const r of rows) {
      console.log(JSON.stringify(r));
    }

    await prisma.$disconnect();
  } catch (e) {
    console.error(e);
    try { await prisma.$disconnect(); } catch {}
    process.exit(1);
  }
})();
