const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

(async () => {
  try {
    const rows = await prisma.$queryRawUnsafe(`
      SELECT p.project_name, p.project_uuid::text,
             j.job_name, j.factory_no, j.floors, j.weight, j.is_ff,
             j.selling_price::text as selling_price,
             j.service_state,
             b.name as brand_name,
             j.job_uuid::text
      FROM projects p
      JOIN job_projects jp ON jp.project_uuid = p.project_uuid
      JOIN jobs j ON j.job_uuid = jp.job_uuid
      LEFT JOIN brands b ON b.uuid = j.brand_uuid
      WHERE p.project_uuid IN (
        '9518b3a0-051a-4732-b24d-e59f121af873',
        'dd779b36-4a8e-4b79-87b6-7c83fb40ba78',
        '34dde880-2eea-4654-919e-454a6ba8c693',
        'd72d257b-3784-4939-8e28-7b69968edcc2'
      )
      ORDER BY p.project_name, j.job_name
    `);

    console.log('Rows:', rows.length);
    for (const r of rows) console.log(JSON.stringify(r));

    await prisma.$disconnect();
  } catch (e) {
    console.error(e);
    try { await prisma.$disconnect(); } catch {}
    process.exit(1);
  }
})();
