          const inserted = await prisma.$queryRawUnsafe(`
            INSERT INTO jobs (job_name, floors, weight, is_ff, factory_no, selling_price, service_state, brand_uuid, insider_uuid)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8::uuid, $9::uuid)
            RETURNING job_uuid::text
          `, def.jobName, def.floors, def.weight, def.isFf, def.factoryNo, def.sellingPrice, def.serviceState, brandUuid, insiderUuid);

