const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

(async () => {
  const projectUuid = '1db66f5a-cd02-4227-8346-8d530e7ddd6b'; // Bagrationi Avenue | 1.1.1 | ავენიუ ბაი ორბი
  const brandUuid = '57e563e9-cfc1-4f9b-885e-c9c59f076275';   // OTIS

  const jobDefs = [
    { jobName: 'PL12', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'PL13', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'PL14', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'PL15', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'SL5', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'SL6', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'SL7', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
    { jobName: 'SL8', floors: 5, weight: 630, isFf: false, factoryNo: null, sellingPrice: null, serviceState: 'Active' },
  ];

  try {
    const projectRows = await prisma.$queryRawUnsafe(`
      SELECT project_uuid::text, project_name, insider_uuid::text
      FROM projects
      WHERE project_uuid = $1::uuid
      LIMIT 1
    `, projectUuid);

    if (!projectRows.length) {
      throw new Error('Target project not found');
    }

    const insiderUuid = projectRows[0].insider_uuid;
    const projectName = projectRows[0].project_name;

    const resultRows = [];

    for (const def of jobDefs) {
      const existingBound = await prisma.$queryRawUnsafe(`
        SELECT j.id, j.job_uuid::text
        FROM jobs j
        JOIN job_projects jp ON jp.job_uuid = j.job_uuid
        WHERE jp.project_uuid = $1::uuid
          AND j.job_name = $2
          AND j.brand_uuid = $3::uuid
        LIMIT 1
      `, projectUuid, def.jobName, brandUuid);

      let jobUuid;
      let action;

      if (existingBound.length > 0) {
        jobUuid = existingBound[0].job_uuid;
        action = 'already_bound';
      } else {
        const existingJob = await prisma.$queryRawUnsafe(`
          SELECT j.id, j.job_uuid::text
          FROM jobs j
          WHERE j.job_name = $1
            AND j.brand_uuid = $2::uuid
            AND j.insider_uuid = $3::uuid
          ORDER BY j.id DESC
          LIMIT 1
        `, def.jobName, brandUuid, insiderUuid);

        if (existingJob.length > 0) {
          jobUuid = existingJob[0].job_uuid;
          await prisma.$executeRawUnsafe(`
            UPDATE jobs
            SET floors = COALESCE(floors, $1),
                weight = COALESCE(weight, $2),
                is_ff = COALESCE(is_ff, $3),
                factory_no = COALESCE(factory_no, $4),
                service_state = COALESCE(service_state, $5),
                updated_at = CURRENT_TIMESTAMP
            WHERE job_uuid = $6::uuid
          `, def.floors, def.weight, def.isFf, def.factoryNo, def.serviceState, jobUuid);

          await prisma.$executeRawUnsafe(`
            INSERT INTO job_projects (job_uuid, project_uuid)
            VALUES ($1::uuid, $2::uuid)
            ON CONFLICT (job_uuid, project_uuid) DO NOTHING
          `, jobUuid, projectUuid);

          action = 'bound_existing_job';
        } else {
          const inserted = await prisma.$queryRawUnsafe(`
            INSERT INTO jobs (job_name, floors, weight, is_ff, factory_no, selling_price, service_state, brand_uuid, insider_uuid)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8::uuid, $9::uuid)
            RETURNING job_uuid::text
          `, def.jobName, def.floors, def.weight, def.isFf, def.factoryNo, def.sellingPrice, def.serviceState, brandUuid, insiderUuid);

          jobUuid = inserted[0].job_uuid;

          await prisma.$executeRawUnsafe(`
            INSERT INTO job_projects (job_uuid, project_uuid)
            VALUES ($1::uuid, $2::uuid)
            ON CONFLICT (job_uuid, project_uuid) DO NOTHING
          `, jobUuid, projectUuid);

          action = 'created_and_bound';
        }
      }

      resultRows.push({
        projectName,
        projectUuid,
        jobName: def.jobName,
        floors: def.floors,
        weight: def.weight,
        isFf: def.isFf,
        factoryNo: def.factoryNo,
        sellingPrice: def.sellingPrice,
        serviceState: def.serviceState,
        brandUuid,
        insiderUuid,
        jobUuid,
        action,
      });
    }

    console.log('Defined jobs count:', resultRows.length);
    for (const r of resultRows) console.log(JSON.stringify(r));

    const verify = await prisma.$queryRawUnsafe(`
      SELECT j.job_name, j.floors, j.weight, j.is_ff, j.factory_no, j.selling_price::text as selling_price,
             j.service_state, b.name as brand_name, j.job_uuid::text
      FROM jobs j
      JOIN job_projects jp ON jp.job_uuid = j.job_uuid
      LEFT JOIN brands b ON b.uuid = j.brand_uuid
      WHERE jp.project_uuid = $1::uuid
      ORDER BY j.job_name
    `, projectUuid);

    console.log('--- VERIFY PROJECT JOBS ---');
    console.log('Total linked jobs:', verify.length);
    for (const v of verify) console.log(JSON.stringify(v));

    await prisma.$disconnect();
  } catch (e) {
    console.error(e);
    try { await prisma.$disconnect(); } catch {}
    process.exit(1);
  }
})();
